// The stores the handlers depend on, as interfaces, and an in-memory implementation with the
// semantics of sql/schema.sql. sql-store.ts implements the same interfaces over Postgres, and
// test/store-contract.test.ts runs one suite against both.
//
// Reads return `unknown`: the handlers parse every row with the schemas in tenant.ts.

import { DEFAULT_LOOK, type ContentPatch } from './tenant.ts';

export interface TurnReservation {
  /** Generated by the handler, so a retried insert cannot count the turn twice. */
  readonly id: string;
  readonly tenantId: string;
  readonly sessionId: string;
  readonly at: Date;
}

export type TurnOutcome =
  | {
      readonly status: 'answered';
      readonly model: string;
      readonly inputTokens: number;
      readonly outputTokens: number;
      /** Null when the gateway could not price the call. The gateway's ledger keeps the bound. */
      readonly costUsd: number | null;
    }
  | { readonly status: 'failed'; readonly errorCode: string };

/** What the public widget endpoints read and write. Every method is scoped to one tenant row. */
export interface TenantStore {
  /** The tenant's full config (TenantConfig), or null when there is no such tenant. */
  getConfig(tenantId: string): Promise<unknown>;
  /** The tenant's plan (Plan), or null. */
  getPlan(tenantId: string): Promise<unknown>;
  /** Turns of this tenant created at or after `since`, in any state. Reserved turns count. */
  countTurnsSince(tenantId: string, since: Date): Promise<unknown>;
  /** Inserts a turn in the reserved state. An existing id succeeds without a second row. */
  reserveTurn(turn: TurnReservation): Promise<void>;
  /** Closes a reserved turn. A turn that is not reserved is left as it is. */
  finishTurn(id: string, outcome: TurnOutcome): Promise<void>;
  /** Deletes a turn that is still reserved: it was refused before the model was called. */
  dropTurn(id: string): Promise<void>;
}

export interface NewTenant {
  readonly tenantId: string;
  readonly accountId: string;
  readonly email: string;
  readonly allowedDomains: readonly string[];
}

/** What the panel reads and writes. */
export interface AccountStore {
  /** The owner (Owner) with this email, or null. Emails are stored lowercase. */
  ownerByEmail(email: string): Promise<unknown>;
  ownerOf(tenantId: string): Promise<unknown>;
  /** Creates the tenant with the default look and its owner, with no password yet. */
  createTenant(tenant: NewTenant): Promise<'created' | 'exists'>;
  /** Replaces the owner's invite nonce: every earlier invite link stops working. */
  setInviteNonce(tenantId: string, nonce: string): Promise<void>;
  /** Sets the password only if `nonce` is still the owner's invite nonce, and clears it. */
  acceptInvite(tenantId: string, nonce: string, passwordHash: string): Promise<boolean>;
  /** Replaces the hash only if it is still `previous`: a rehash on login never undoes a password change. */
  replacePasswordHash(tenantId: string, previous: string, next: string): Promise<boolean>;
  saveContent(tenantId: string, patch: ContentPatch): Promise<void>;
}

/** A new tenant's row, the same defaults as the SQL columns. */
export const DEFAULT_ROW = {
  ...DEFAULT_LOOK,
  suggestedQuestions: [] as string[],
  tonePreset: 'friendly',
  tone: '',
  context: '',
  faq: '',
};

interface TenantRow {
  config: Record<string, unknown>;
  plan: { status: string; monthlyTurns: number | null };
  owner: { email: string; passwordHash: string | null; inviteNonce: string | null };
}

interface TurnRow {
  readonly tenantId: string;
  readonly sessionId: string;
  readonly at: Date;
  outcome: TurnOutcome | null;
}

/**
 * One process, one Map per table. Tenants are isolated the way the SQL tables isolate them: every
 * method takes the tenant id and touches only that tenant's rows.
 */
export class MemoryStore implements TenantStore, AccountStore {
  readonly tenants = new Map<string, TenantRow>();
  readonly turns = new Map<string, TurnRow>();

  /** For seeding and tests: a tenant with a full config row and a plan. */
  putTenant(config: Readonly<Record<string, unknown>> & { readonly tenantId: string; readonly email?: string }, plan: TenantRow['plan'] = { status: 'active', monthlyTurns: null }): void {
    const { email, ...rest } = config;
    const previous = this.tenants.get(config.tenantId);
    this.tenants.set(config.tenantId, {
      config: { ...DEFAULT_ROW, ...rest },
      plan: { ...plan },
      owner: previous?.owner ?? { email: (email ?? `owner@${config.tenantId}.example`).toLowerCase(), passwordHash: null, inviteNonce: null },
    });
  }

  setPlan(tenantId: string, plan: TenantRow['plan']): void {
    const row = this.tenants.get(tenantId);
    if (row) row.plan = { ...plan };
  }

  async getConfig(tenantId: string): Promise<unknown> {
    const row = this.tenants.get(tenantId);
    return row ? structuredClone(row.config) : null;
  }

  async getPlan(tenantId: string): Promise<unknown> {
    const row = this.tenants.get(tenantId);
    return row ? { ...row.plan } : null;
  }

  async countTurnsSince(tenantId: string, since: Date): Promise<unknown> {
    let n = 0;
    for (const turn of this.turns.values()) if (turn.tenantId === tenantId && turn.at.getTime() >= since.getTime()) n += 1;
    return n;
  }

  async reserveTurn(turn: TurnReservation): Promise<void> {
    if (this.turns.has(turn.id)) return;
    // The foreign key of widget_turns.
    if (!this.tenants.has(turn.tenantId)) throw new Error('widget_turns_tenant_id_fkey');
    this.turns.set(turn.id, { tenantId: turn.tenantId, sessionId: turn.sessionId, at: new Date(turn.at), outcome: null });
  }

  async finishTurn(id: string, outcome: TurnOutcome): Promise<void> {
    const turn = this.turns.get(id);
    if (turn && turn.outcome === null) turn.outcome = outcome;
  }

  async dropTurn(id: string): Promise<void> {
    const turn = this.turns.get(id);
    if (turn && turn.outcome === null) this.turns.delete(id);
  }

  async ownerByEmail(email: string): Promise<unknown> {
    const wanted = email.toLowerCase();
    for (const [tenantId, row] of this.tenants) if (row.owner.email === wanted) return { tenantId, ...row.owner };
    return null;
  }

  async ownerOf(tenantId: string): Promise<unknown> {
    const row = this.tenants.get(tenantId);
    return row ? { tenantId, ...row.owner } : null;
  }

  async createTenant(tenant: NewTenant): Promise<'created' | 'exists'> {
    const email = tenant.email.toLowerCase();
    if (this.tenants.has(tenant.tenantId)) return 'exists';
    // The unique index on widget_owners.email.
    for (const row of this.tenants.values()) if (row.owner.email === email) return 'exists';
    this.tenants.set(tenant.tenantId, {
      config: { ...DEFAULT_ROW, tenantId: tenant.tenantId, accountId: tenant.accountId, allowedDomains: [...tenant.allowedDomains] },
      plan: { status: 'active', monthlyTurns: null },
      owner: { email, passwordHash: null, inviteNonce: null },
    });
    return 'created';
  }

  async setInviteNonce(tenantId: string, nonce: string): Promise<void> {
    const row = this.tenants.get(tenantId);
    if (row) row.owner.inviteNonce = nonce;
  }

  async acceptInvite(tenantId: string, nonce: string, passwordHash: string): Promise<boolean> {
    const row = this.tenants.get(tenantId);
    if (!row || row.owner.inviteNonce === null || row.owner.inviteNonce !== nonce) return false;
    row.owner.passwordHash = passwordHash;
    row.owner.inviteNonce = null;
    return true;
  }

  async replacePasswordHash(tenantId: string, previous: string, next: string): Promise<boolean> {
    const row = this.tenants.get(tenantId);
    if (!row || row.owner.passwordHash !== previous) return false;
    row.owner.passwordHash = next;
    return true;
  }

  async saveContent(tenantId: string, patch: ContentPatch): Promise<void> {
    const row = this.tenants.get(tenantId);
    if (!row) throw new Error('no such tenant');
    for (const [key, value] of Object.entries(patch)) if (value !== undefined) row.config[key] = Array.isArray(value) ? [...value] : value;
  }
}
